bool DeviceCache::hasMipmapImage(int camId)
void DeviceCache::addMipmapImageFromDevice(int camId,
                                           int minDownscale,
                                           int maxDownscale,
                                           std::shared_ptr<CudaDeviceMemoryPitched<CudaRGBA, 2>> img_dmpPtr,
                                           const mvsUtils::MultiViewParams& mp)
{
    // cheshire (step 6m): addMipmapImage from the LRU insertion on, with the image from the device
    SingleDeviceCache& currentDeviceCache = getCurrentDeviceCache();
    const IndexT viewId = mp.getViewId(camId);
    int deviceMipmapId;
    const bool newInsertion = currentDeviceCache.mipmapCache.insert(camId, &deviceMipmapId);
    if (!newInsertion)
    {
        ALICEVISION_LOG_TRACE("Add mipmap image on device cache: already on cache (id: " << camId << ", view id: " << viewId << ").");
        return;
    }
    ALICEVISION_LOG_TRACE("Add mipmap image on device cache from the device (id: " << camId << ", view id: " << viewId << ").");
    currentDeviceCache.mipmaps.at(deviceMipmapId)->fillFromDevice(std::move(img_dmpPtr), minDownscale, maxDownscale);
}

